/** Comparable immutable-byte tool benchmark; never a CI, deployment or <600s acceptance receipt. */
import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{readFileSync,writeFileSync,mkdtempSync}from'node:fs';import{join,resolve}from'node:path';import{tmpdir}from'node:os';import{createHash}from'node:crypto';import{performance}from'node:perf_hooks';import{createCommittedSourceReader}from'../../../scripts/improve/committed-source-blobs.ts';
const root=resolve(process.argv[2]??'.'),candidate=execFileSync('git',['-C',root,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),output=process.argv[3];assert(output);
const git=(...args)=>execFileSync('git',['-C',root,...args],{maxBuffer:16*1024**2});const catalogue='lib/system-testing/catalogue.json';const paths=[...new Set(JSON.parse(git('show',candidate+':'+catalogue)).entries.flatMap(e=>e.sources))].sort();assert(paths.length>0);
const digest=b=>createHash('sha256').update(b).digest('hex');const legacy=()=>new Map([catalogue,...paths].map(path=>{const mode=git('ls-tree',candidate,'--',path).toString();assert(/^100(?:644|755) blob [a-f0-9]{40}\t/.test(mode));return[path,git('show',candidate+':'+path)];}));
const batched=()=>{const reader=createCommittedSourceReader(root,candidate),all=new Map(reader.read([catalogue],8*1024**2));for(const[p,b]of reader.read(paths))all.set(p,b);return all;};
const directory=mkdtempSync(join(tmpdir(),'source-benchmark-')),runs=[];let expected;
for(let iteration=0;iteration<3;iteration++)for(const[name,read]of iteration%2?[['batched',batched],['legacy',legacy]]:[['legacy',legacy],['batched',batched]]){const trace=join(directory,name+'-'+iteration+'.jsonl');const old=process.env.GIT_TRACE2_EVENT;process.env.GIT_TRACE2_EVENT=trace;let values,ms;try{const started=performance.now();values=read();ms=performance.now()-started;}finally{if(old===undefined)delete process.env.GIT_TRACE2_EVENT;else process.env.GIT_TRACE2_EVENT=old;}const hashes=[...values].map(([path,bytes])=>({path,sha256:digest(bytes)}));if(expected)assert.deepEqual(hashes,expected);else expected=hashes;const events=readFileSync(trace,'utf8').trim().split('\n').map(l=>JSON.parse(l));runs.push({name,iteration,elapsedMs:ms,gitProcesses:events.filter(e=>e.event==='start').length,bytes:[...values.values()].reduce((a,b)=>a+b.length,0)});}
const median=name=>runs.filter(r=>r.name===name).map(r=>r.elapsedMs).sort((a,b)=>a-b)[1];const result={kind:'IMMUTABLE_SOURCE_TOOL_BENCHMARK_NOT_END_TO_END_RELEASE',candidate,paths:paths.length,catalogueIncluded:true,hashesEqual:true,sourceBytesDigest:digest(Buffer.from(JSON.stringify(expected))),runs,medianMs:{legacy:median('legacy'),batched:median('batched')},fullCleanHeadAndInstalledFileChecksRetainedInConsumer:true,applicationTestsRun:false,applicationBuildRun:false,releaseAuthorized:false,goalAchieved:false};writeFileSync(output,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
